// Stops on unfinished Config, then re-validates the payload from the site.
// GENERATED by automation/scripts/build-n8n-workflow.mjs. Edit the repo sources, not this node.

const ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;", "`": "&#96;" };

function escapeHtml(value) {
  if (value === null || value === undefined) return "";
  return String(value).replace(/[&<>"'`]/g, (c) => ESCAPES[c]);
}

const PLACEHOLDER = "REPLACE_ME";

const CONFIG_KEYS = [
  "HUBSPOT_PORTAL_ID",
  "SUPPORT_NOTIFY_TO",
  "MAIL_FROM_ACK",
  "MAIL_FROM_NOTIFY",
  "REPLY_TO_ACK",
  "SITE_URL",
  "TIMEZONE",
];

/** Config keys that are empty or still hold the REPLACE_ME placeholder. */
function findPlaceholders(config) {
  return CONFIG_KEYS.filter((k) => {
    const v = config?.[k];
    return v === undefined || v === null || String(v).trim() === "" || String(v).includes(PLACEHOLDER);
  });
}

/** An Error whose message carries the raw payload, so the Error Workflow can email it to support. */
function errorWithPayload(message, payload) {
  let raw;
  try {
    raw = JSON.stringify(payload, null, 2);
  } catch {
    raw = String(payload);
  }
  return new Error(`${message}\n\nPAYLOAD:${raw}`);
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const EMAIL = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;

/**
 * Defense in depth: the site already validated with zod. This makes sure the
 * webhook only acts on well-formed inquiries even if something else calls it.
 */
function validatePayload(p, options) {
  const errors = [];
  const str = (v) => (typeof v === "string" ? v.trim() : "");
  if (!p || typeof p !== "object" || Array.isArray(p)) return { valid: false, errors: ["body must be a JSON object"] };

  if (!UUID.test(str(p.submissionId))) errors.push("submissionId");
  const name = str(p.name);
  if (name.length < 1 || name.length > 120) errors.push("name");
  const email = str(p.email).toLowerCase();
  if (!EMAIL.test(email) || email.length > 254) errors.push("email");
  if (p.company !== undefined && (typeof p.company !== "string" || p.company.length > 160)) errors.push("company");
  if (!options.help.includes(p.help)) errors.push("help");
  if (!options.budget.includes(p.budget)) errors.push("budget");
  if (!options.stage.includes(p.stage)) errors.push("stage");
  const project = str(p.project);
  if (project.length < 10 || project.length > 5000) errors.push("project");
  if (p.marketingOptIn !== undefined && typeof p.marketingOptIn !== "boolean") errors.push("marketingOptIn");
  if (Number.isNaN(Date.parse(p.submittedAt))) errors.push("submittedAt");

  if (errors.length) return { valid: false, errors };
  return {
    valid: true,
    errors: [],
    payload: {
      ...p,
      name,
      email,
      company: str(p.company),
      project,
      marketingOptIn: p.marketingOptIn === true,
      attribution: p.attribution && typeof p.attribution === "object" ? p.attribution : {},
    },
  };
}

/* ---------------- HubSpot ---------------- */

/** Properties read back from an existing contact so the rules below can protect them. */
const HUBSPOT_READ_PROPS = [
  "lifecyclestage",
  "hs_lead_status",
  "adbyrd_marketing_opt_in",
  "adbyrd_first_touch_source",
  "adbyrd_first_touch_medium",
  "adbyrd_first_touch_campaign",
  "adbyrd_landing_page",
];

function hubspotSearchBody(email) {
  return {
    filterGroups: [{ filters: [{ propertyName: "email", operator: "EQ", value: email }] }],
    properties: HUBSPOT_READ_PROPS,
    limit: 1,
  };
}

const OPTIONS = {"help":["AI Phone Receptionist","Booking & Payment App","iPhone / Mobile App","Workflow Automation","Connecting My Tools","Care & Support Plan","Not sure yet"],"stage":["Just exploring","I know the problem, not the solution","I know what I want built","Ready to start soon"],"budget":["Not sure yet","Under $3,000","$3,000 – $5,000","$5,000 – $7,500","$7,500+"]};

// ---- node logic ----
const body = $('Webhook').first().json.body;
const config = $('Config').first().json;
const missing = findPlaceholders(config);
if (missing.length) {
  throw errorWithPayload(`Config node is not finished (still empty or REPLACE_ME): ${missing.join(', ')}`, body);
}
const result = validatePayload(body, OPTIONS);
if (!result.valid) return [{ json: { valid: false, errors: result.errors } }];
return [{ json: { valid: true, payload: result.payload, config, search: hubspotSearchBody(result.payload.email) } }];

// Applies the returning-contact rules (see prepareContact in workflow-lib.mjs).
// GENERATED by automation/scripts/build-n8n-workflow.mjs. Edit the repo sources, not this node.

/** Strip CR/LF from header-like values (subjects, names in From lines). */
function oneLine(value, max = 200) {
  return String(value ?? "")
    .replace(/[\r\n\t]+/g, " ")
    .replace(/\s{2,}/g, " ")
    .trim()
    .slice(0, max);
}

function splitName(name) {
  const clean = oneLine(name, 120);
  const i = clean.indexOf(" ");
  return i === -1 ? { first: clean, last: "" } : { first: clean.slice(0, i), last: clean.slice(i + 1).trim() };
}

/** Normalizes the "HubSpot: Find contact" HTTP response (full response, never-error mode). */
function readFind(resp) {
  const status = resp?.statusCode;
  if (status !== 200 || !resp?.body) return { ok: false, contact: null, status: status ?? "network" };
  const hit = resp.body.results?.[0];
  return { ok: true, contact: hit ? { id: String(hit.id), properties: hit.properties ?? {} } : null };
}

const empty = (v) => v === undefined || v === null || String(v).trim() === "";

/**
 * Builds the contact properties for a create or an update.
 * Returning contacts keep what the team has already set:
 *  - lifecyclestage → "lead" only when new, empty, or still "subscriber" (never a downgrade)
 *  - hs_lead_status → "NEW" only when new or empty (keeps "In progress", "Connected", …)
 *  - adbyrd_marketing_opt_in → only ever written as "true"; an unticked box never clears it
 *  - first-touch fields and landing page → only when empty (first touch is first touch)
 *  - everything else (service, budget, stage, description, last touch) → latest inquiry wins;
 *    the Note on the contact keeps the full history
 */
function prepareContact(payload, find) {
  const existing = find?.contact ?? null;
  const cur = existing?.properties ?? {};
  const { first, last } = splitName(payload.name);
  const a = payload.attribution ?? {};
  const ft = a.first ?? null;
  const lt = a.last ?? null;
  const cap = (v, n = 255) => (v === undefined || v === null ? "" : String(v).slice(0, n));

  const props = {
    email: payload.email,
    firstname: first,
    adbyrd_service_interest: payload.help,
    adbyrd_budget_range: payload.budget,
    adbyrd_project_stage: payload.stage,
    adbyrd_project_description: cap(payload.project, 65000),
    adbyrd_last_submission_id: payload.submissionId,
  };
  if (last) props.lastname = last;
  if (payload.company) props.company = cap(payload.company, 160);

  if (lt) {
    props.adbyrd_last_touch_source = cap(lt.source);
    props.adbyrd_last_touch_medium = cap(lt.medium);
    props.adbyrd_last_touch_campaign = cap(lt.campaign);
  }

  const setIfEmpty = (key, value) => {
    if (!empty(value) && (!existing || empty(cur[key]))) props[key] = value;
  };
  if (ft) {
    setIfEmpty("adbyrd_first_touch_source", cap(ft.source));
    setIfEmpty("adbyrd_first_touch_medium", cap(ft.medium));
    setIfEmpty("adbyrd_first_touch_campaign", cap(ft.campaign));
  }
  setIfEmpty("adbyrd_landing_page", cap(ft?.landing_page ?? lt?.landing_page, 2000));

  if (!existing || empty(cur.lifecyclestage) || cur.lifecyclestage === "subscriber") props.lifecyclestage = "lead";
  if (!existing || empty(cur.hs_lead_status)) props.hs_lead_status = "NEW";
  if (payload.marketingOptIn === true) props.adbyrd_marketing_opt_in = "true";

  return {
    mode: existing ? "update" : "create",
    contactId: existing?.id ?? null,
    lookupFailed: find ? !find.ok : true,
    properties: props,
  };
}

// ---- node logic ----
const { payload, config } = $('Validate').first().json;
return [{ json: prepareContact(payload, readFind($input.first().json)) }];

// A 409 means the contact exists after all, so update it by ID instead.
// GENERATED by automation/scripts/build-n8n-workflow.mjs. Edit the repo sources, not this node.

/** Properties read back from an existing contact so the rules below can protect them. */
const HUBSPOT_READ_PROPS = [
  "lifecyclestage",
  "hs_lead_status",
  "adbyrd_marketing_opt_in",
  "adbyrd_first_touch_source",
  "adbyrd_first_touch_medium",
  "adbyrd_first_touch_campaign",
  "adbyrd_landing_page",
];

/** Never written on the 409-conflict fallback, where we couldn't read the contact first. */
const PROTECTED = new Set(HUBSPOT_READ_PROPS);

/**
 * The create call returned 409 (the contact exists but search didn't find it,
 * e.g. HubSpot's search index lagging a few seconds). Fall back to an update
 * by the existing ID, without the protected fields we couldn't read.
 */
function conflictUpdate(resp, prepared) {
  if (resp?.statusCode !== 409) return null;
  const msg = String(resp.body?.message ?? "");
  const id = msg.match(/Existing ID:\s*(\d+)/i)?.[1];
  if (!id) return null;
  const properties = Object.fromEntries(Object.entries(prepared.properties).filter(([k]) => !PROTECTED.has(k)));
  if (prepared.properties.adbyrd_marketing_opt_in === "true") properties.adbyrd_marketing_opt_in = "true";
  return { mode: "update", contactId: id, lookupFailed: prepared.lookupFailed, properties };
}

/** Normalizes the create/update response into the CRM status the emails use. */
function contactResult(resp, mode) {
  const ok = (resp?.statusCode === 200 || resp?.statusCode === 201) && resp?.body?.id;
  return ok
    ? { contactOk: true, contactId: String(resp.body.id), created: mode === "create", status: resp.statusCode }
    : {
        contactOk: false,
        contactId: null,
        created: false,
        status: resp?.statusCode ?? "network",
        message: String(resp?.body?.message ?? resp?.error?.message ?? "no response").slice(0, 500),
      };
}

// ---- node logic ----
const prepared = $('Prepare contact').first().json;
const resp = $input.first().json;
const retry = conflictUpdate(resp, prepared);
if (retry) return [{ json: { next: 'update', ...retry } }];
return [{ json: { next: 'done', crm: contactResult(resp, 'create') } }];

// CRM status for the support email, plus the Note to log on the contact.
// GENERATED by automation/scripts/build-n8n-workflow.mjs. Edit the repo sources, not this node.

const ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;", "`": "&#96;" };

function escapeHtml(value) {
  if (value === null || value === undefined) return "";
  return String(value).replace(/[&<>"'`]/g, (c) => ESCAPES[c]);
}

/** Escape first, then turn line breaks into <br>. */
function nl2br(value) {
  return escapeHtml(value).replace(/\r\n|\r|\n/g, "<br>\n");
}

function formatWhen(iso, timeZone) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return String(iso ?? "");
  try {
    return new Intl.DateTimeFormat("en-US", {
      timeZone,
      weekday: "short",
      month: "short",
      day: "numeric",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      timeZoneName: "short",
    }).format(d);
  } catch {
    return d.toISOString();
  }
}

/** Normalizes the create/update response into the CRM status the emails use. */
function contactResult(resp, mode) {
  const ok = (resp?.statusCode === 200 || resp?.statusCode === 201) && resp?.body?.id;
  return ok
    ? { contactOk: true, contactId: String(resp.body.id), created: mode === "create", status: resp.statusCode }
    : {
        contactOk: false,
        contactId: null,
        created: false,
        status: resp?.statusCode ?? "network",
        message: String(resp?.body?.message ?? resp?.error?.message ?? "no response").slice(0, 500),
      };
}

/** Note on the contact: the full inquiry plus attribution. hs_timestamp is required by HubSpot. */
function buildNote(payload, contactId, timeZone) {
  const a = payload.attribution ?? {};
  const touch = (t) =>
    t
      ? [
          `${t.source} / ${t.medium}`,
          t.campaign && `campaign ${t.campaign}`,
          t.click_id_type && `click ID ${t.click_id_type}`,
          t.landing_page && `landed on ${t.landing_page}`,
          t.referrer && `from ${t.referrer}`,
        ]
          .filter(Boolean)
          .join(" · ")
      : "—";
  const row = (k, v) => `<strong>${escapeHtml(k)}:</strong> ${escapeHtml(v)}<br>`;
  const body =
    `<p><strong>Website inquiry ${escapeHtml(payload.submissionId)}</strong><br>` +
    `${escapeHtml(formatWhen(payload.submittedAt, timeZone))}</p>` +
    `<p>` +
    row("Name", payload.name) +
    row("Business", payload.company || "—") +
    row("Email", payload.email) +
    row("Service", payload.help) +
    row("Budget", payload.budget) +
    row("Stage", payload.stage) +
    row("Marketing opt-in", payload.marketingOptIn ? "Yes" : "No") +
    `</p><p><strong>Message</strong><br>${nl2br(payload.project)}</p>` +
    `<p>` +
    row("First touch", touch(a.first)) +
    row("Last touch", touch(a.last)) +
    row("Page", payload.pageUrl || "—") +
    `</p>`;
  return {
    properties: { hs_timestamp: payload.submittedAt, hs_note_body: body },
    associations: [
      {
        to: { id: String(contactId) },
        types: [{ associationCategory: "HUBSPOT_DEFINED", associationTypeId: 202 }],
      },
    ],
  };
}

/* ---------------- Resend ---------------- */

// ---- node logic ----
const { payload, config } = $('Validate').first().json;
const j = $input.first().json;
const crm = j.crm ?? contactResult(j, 'update');
const note = crm.contactOk ? buildNote(payload, crm.contactId, config.TIMEZONE) : null;
return [{ json: { crm, note } }];

// Fills both email templates. Every user value is HTML-escaped (automation/emails/render.mjs).
// GENERATED by automation/scripts/build-n8n-workflow.mjs. Edit the repo sources, not this node.

const ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;", "`": "&#96;" };

function escapeHtml(value) {
  if (value === null || value === undefined) return "";
  return String(value).replace(/[&<>"'`]/g, (c) => ESCAPES[c]);
}

/** Escape first, then turn line breaks into <br>. */
function nl2br(value) {
  return escapeHtml(value).replace(/\r\n|\r|\n/g, "<br>\n");
}

/** Strip CR/LF from header-like values (subjects, names in From lines). */
function oneLine(value, max = 200) {
  return String(value ?? "")
    .replace(/[\r\n\t]+/g, " ")
    .replace(/\s{2,}/g, " ")
    .trim()
    .slice(0, max);
}

/**
 * Replaces {{token}} placeholders. In HTML mode, values are escaped unless the
 * token name ends in "Html". Unknown tokens throw, so a template typo fails
 * loudly (and lands in the Error Workflow) instead of shipping "{{oops}}".
 */
function fill(template, vars, { html = true } = {}) {
  return template.replace(/\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g, (_, key) => {
    if (!(key in vars)) throw new Error(`Email template token not provided: ${key}`);
    const v = vars[key];
    if (!html || key.endsWith("Html")) return v === null || v === undefined ? "" : String(v);
    return escapeHtml(v);
  });
}

function splitName(name) {
  const clean = oneLine(name, 120);
  const i = clean.indexOf(" ");
  return i === -1 ? { first: clean, last: "" } : { first: clean.slice(0, i), last: clean.slice(i + 1).trim() };
}

function formatWhen(iso, timeZone) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return String(iso ?? "");
  try {
    return new Intl.DateTimeFormat("en-US", {
      timeZone,
      weekday: "short",
      month: "short",
      day: "numeric",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      timeZoneName: "short",
    }).format(d);
  } catch {
    return d.toISOString();
  }
}

function hubspotContactUrl(portalId, contactId) {
  return `https://app.hubspot.com/contacts/${encodeURIComponent(portalId)}/record/0-1/${encodeURIComponent(contactId)}`;
}

/* ---------- shared fragment styles (inline, email-safe) ---------- */

const FONT = "Inter, Sora, 'Segoe UI', Roboto, 'Helvetica Neue', Helvetica, Arial, sans-serif";

const C = {
  ink: "#121726",
  night: "#1c2433",
  steel: "#4f5f6e",
  mist: "#a8bfc0",
  ember: "#e07a3f",
  ember2: "#c9642b",
  fog: "#e9ecea",
  ivory: "#f6f4ef",
  slate: "#566170",
  line: "#e2e3dd",
};

function kvRowsHtml(rows) {
  return rows
    .map(
      ([label, valueHtml], i) =>
        `<tr><td class="kv-l dm-bd dm-muted" valign="top" style="padding:12px 16px 12px 0;${i ? `border-top:1px solid ${C.line};` : ""}width:150px;font-family:${FONT};font-size:12px;line-height:18px;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;color:${C.slate};">${escapeHtml(label)}</td>` +
        `<td class="dm-bd dm-text" valign="top" style="padding:12px 0;${i ? `border-top:1px solid ${C.line};` : ""}font-family:${FONT};font-size:15px;line-height:22px;color:${C.ink};word-break:break-word;">${valueHtml}</td></tr>`,
    )
    .join("\n");
}

function kvRowsText(rows) {
  return rows.map(([label, value]) => `${label}: ${value}`).join("\n");
}

function nextStepsHtml(steps) {
  return steps
    .map((s, i) => {
      const badge = i === 0 ? `background-color:${C.ember};color:${C.ink};` : `background-color:${C.night};color:${C.mist};`;
      return (
        `<tr><td valign="top" width="52" style="padding:0 0 18px 0;">` +
        `<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" valign="middle" width="36" height="36" style="${badge}width:36px;height:36px;border-radius:7px;font-family:${FONT};font-size:13px;font-weight:700;">0${i + 1}</td></tr></table>` +
        `</td><td valign="top" style="padding:0 0 18px 0;font-family:${FONT};">` +
        `<p class="dm-text" style="margin:0;font-size:16px;line-height:22px;font-weight:600;color:${C.ink};">${escapeHtml(s.title)}</p>` +
        `<p class="dm-muted" style="margin:4px 0 0 0;font-size:14px;line-height:21px;color:${C.slate};">${escapeHtml(s.body)}</p>` +
        `</td></tr>`
      );
    })
    .join("\n");
}

function socialHtml(socials, siteUrl) {
  return socials
    .map(
      (s) =>
        `<td style="padding:0 6px;"><a href="${escapeHtml(s.url)}" target="_blank" style="text-decoration:none;"><img src="${escapeHtml(`${siteUrl}/email/icon_${s.platform}.jpg`)}" width="28" height="28" alt="${escapeHtml(`Adbyrd on ${s.label}`)}" style="display:block;width:28px;height:28px;border:0;border-radius:4px;"></a></td>`,
    )
    .join("");
}

function legalHtml(links, siteUrl) {
  return links
    .map(
      (l) =>
        `<a href="${escapeHtml(siteUrl + l.path)}" target="_blank" class="dm-muted" style="color:${C.slate};text-decoration:underline;">${escapeHtml(l.label)}</a>`,
    )
    .join(` <span style="color:${C.mist};">&middot;</span> `);
}

function touchRows(t) {
  if (!t) return [["Touch", "—"]];
  return [
    ["Source / medium", `${t.source || "—"} / ${t.medium || "—"}`],
    ["Campaign", t.campaign || "—"],
    ["Landing page", t.landing_page || "—"],
    ["Referrer", t.referrer || "—"],
    ["Click ID type", t.click_id_type || "—"],
  ];
}

function attributionHtml(attribution) {
  const col = (title, t) =>
    `<td class="stack" valign="top" width="50%" style="padding:0 8px 16px 0;">` +
    `<p class="dm-muted" style="margin:0 0 6px 0;font-family:${FONT};font-size:12px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:${C.steel};">${escapeHtml(title)}</p>` +
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">` +
    touchRows(t)
      .map(
        ([k, v]) =>
          `<tr><td class="dm-muted" style="padding:3px 0;font-family:${FONT};font-size:12px;line-height:17px;color:${C.slate};width:96px;" valign="top">${escapeHtml(k)}</td><td class="dm-text" style="padding:3px 0;font-family:${FONT};font-size:13px;line-height:17px;color:${C.ink};word-break:break-all;" valign="top">${escapeHtml(v)}</td></tr>`,
      )
      .join("") +
    `</table></td>`;
  return `<tr>${col("First touch", attribution?.first)}${col("Last touch", attribution?.last)}</tr>`;
}

function attributionText(attribution) {
  const block = (title, t) => `${title}\n` + touchRows(t).map(([k, v]) => `  ${k}: ${v}`).join("\n");
  return `${block("First touch", attribution?.first)}\n${block("Last touch", attribution?.last)}`;
}

function crmBanner(crm, portalId) {
  if (crm?.contactOk && crm.contactId) {
    const url = hubspotContactUrl(portalId, crm.contactId);
    const noteWarn = crm.noteOk === false ? " (the inquiry note couldn't be logged; it's all below)" : "";
    return {
      html:
        `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td class="dm-card2 dm-text" style="padding:14px 18px;background-color:#eef3f3;border:1px solid ${C.mist};border-radius:8px;font-family:${FONT};font-size:14px;line-height:20px;color:${C.ink};">` +
        `<strong>${crm.created ? "New contact" : "Existing contact"} synced to HubSpot.</strong>${escapeHtml(noteWarn)} ` +
        `<a href="${escapeHtml(url)}" target="_blank" class="dm-muted" style="color:${C.steel};font-weight:600;text-decoration:underline;">Open contact record&nbsp;&rarr;</a>` +
        `</td></tr></table>`,
      text: `HubSpot: ${crm.created ? "new" : "existing"} contact synced${noteWarn}. ${url}`,
    };
  }
  return {
    html:
      `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="padding:14px 18px;background-color:#fbece3;border:1px solid ${C.ember2};border-radius:8px;font-family:${FONT};font-size:14px;line-height:20px;color:${C.ink};">` +
      `<strong>&#9888; CRM sync failed.</strong> This contact was not saved to HubSpot. Add it by hand from the details below.` +
      `</td></tr></table>`,
    text: "⚠ CRM sync failed. This contact was not saved to HubSpot. Add it by hand from the details below.",
  };
}

/**
 * Renders both emails and the Resend request bodies.
 * @param {object} args
 * @param {object} args.payload    validated inquiry from the site (see project/app/api/inquiry/route.ts)
 * @param {object} args.config     values from the workflow's Config node
 * @param {object} args.site       contact, nextSteps, socials, legal (from project/lib, inlined at build time)
 * @param {object} args.templates  { ackHtml, ackText, notifyHtml, notifyText }
 * @param {object} [args.crm]      { contactOk, contactId, created, noteOk }
 */
function renderInquiryEmails({ payload, config, site, templates, crm }) {
  const siteUrl = String(config.SITE_URL || "https://adbyrd.com").replace(/\/$/, "");
  const { first: firstName } = splitName(payload.name);
  const when = formatWhen(payload.submittedAt, config.TIMEZONE || "America/Detroit");
  const year = String(new Date(payload.submittedAt || Date.now()).getFullYear());
  const company = oneLine(payload.company) || "—";
  const optIn = payload.marketingOptIn === true ? "Yes" : "No";

  const common = {
    siteUrl,
    logoUrl: `${siteUrl}/email/icon_w_text.jpg`,
    year,
    phoneDisplay: site.contact.phoneDisplay,
    phoneHref: `tel:${site.contact.phoneE164}`,
    supportEmail: site.contact.email,
    supportEmailHref: `mailto:${site.contact.email}`,
    addressOneLine: site.contact.addressOneLine,
    submissionId: payload.submissionId,
  };

  /* ----- acknowledgment (to the submitter) ----- */
  const recap = [
    ["Service", payload.help],
    ["Budget", payload.budget],
    ["Stage", payload.stage],
  ];
  const ackSubject = oneLine(`We got your project inquiry, ${firstName}`);
  const ackVars = {
    ...common,
    preheader: "Thanks for reaching out. Here's a copy of what you sent and what happens next.",
    firstName,
    recapHtml: kvRowsHtml(recap.map(([k, v]) => [k, escapeHtml(v)])),
    recapText: kvRowsText(recap),
    projectHtml: nl2br(payload.project),
    projectText: String(payload.project ?? ""),
    nextStepsHtml: nextStepsHtml(site.nextSteps),
    nextStepsText: site.nextSteps.map((s, i) => `0${i + 1}  ${s.title}\n    ${s.body}`).join("\n"),
    socialHtml: socialHtml(site.socials, siteUrl),
    socialText: site.socials.map((s) => `${s.label}: ${s.url}`).join("\n"),
    legalHtml: legalHtml(site.legal, siteUrl),
    legalText: site.legal.map((l) => `${l.label}: ${siteUrl}${l.path}`).join("\n"),
  };

  /* ----- notification (to support) ----- */
  const banner = crmBanner(crm, config.HUBSPOT_PORTAL_ID);
  const emailHref = `mailto:${encodeURI(payload.email)}?subject=${encodeURIComponent("Re: Your Adbyrd project inquiry")}`;
  const fields = [
    ["Name", oneLine(payload.name)],
    ["Business", company],
    ["Email", payload.email],
    ["Service", payload.help],
    ["Budget", payload.budget],
    ["Stage", payload.stage],
    ["Marketing opt-in", optIn],
  ];
  const meta = [
    ["Submission ID", payload.submissionId],
    ["Submitted", when],
    ["Page", payload.pageUrl || "—"],
    ["Source", payload.source || "—"],
    ["User agent", payload.userAgent || "—"],
  ];
  const notifySubject = oneLine(`New inquiry: ${oneLine(payload.name, 80)} · ${payload.help} · ${payload.budget}`, 250);
  const notifyVars = {
    ...common,
    preheader: `${oneLine(payload.name, 80)} (${company}) · ${payload.help} · ${payload.budget}`,
    name: oneLine(payload.name),
    email: payload.email,
    emailHref,
    crmBannerHtml: banner.html,
    crmText: banner.text,
    fieldsHtml: kvRowsHtml(
      fields.map(([k, v]) => [
        k,
        k === "Email"
          ? `<a href="${escapeHtml(emailHref)}" style="color:${C.steel};font-weight:600;text-decoration:underline;">${escapeHtml(v)}</a>`
          : escapeHtml(v),
      ]),
    ),
    fieldsText: kvRowsText(fields),
    projectHtml: nl2br(payload.project),
    projectText: String(payload.project ?? ""),
    attributionHtml: attributionHtml(payload.attribution),
    attributionText: attributionText(payload.attribution),
    metaHtml: kvRowsHtml(meta.map(([k, v]) => [k, escapeHtml(v)])),
    metaText: kvRowsText(meta),
  };

  const ack = {
    subject: ackSubject,
    html: fill(templates.ackHtml, ackVars),
    text: fill(templates.ackText, ackVars, { html: false }),
  };
  const notify = {
    subject: notifySubject,
    html: fill(templates.notifyHtml, notifyVars),
    text: fill(templates.notifyText, notifyVars, { html: false }),
  };

  const supportTo = String(config.SUPPORT_NOTIFY_TO || site.contact.email)
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);

  return {
    ack: {
      ...ack,
      idempotencyKey: `inquiry-ack/${payload.submissionId}`,
      body: {
        from: config.MAIL_FROM_ACK,
        to: [payload.email],
        reply_to: config.REPLY_TO_ACK || site.contact.email,
        subject: ack.subject,
        html: ack.html,
        text: ack.text,
        tags: [{ name: "type", value: "inquiry_ack" }],
      },
    },
    notify: {
      ...notify,
      idempotencyKey: `inquiry-notify/${payload.submissionId}`,
      body: {
        from: config.MAIL_FROM_NOTIFY,
        to: supportTo,
        reply_to: payload.email,
        subject: notify.subject,
        html: notify.html,
        text: notify.text,
        tags: [{ name: "type", value: "inquiry_notify" }],
      },
    },
  };
}

/** An Error whose message carries the raw payload, so the Error Workflow can email it to support. */
function errorWithPayload(message, payload) {
  let raw;
  try {
    raw = JSON.stringify(payload, null, 2);
  } catch {
    raw = String(payload);
  }
  return new Error(`${message}\n\nPAYLOAD:${raw}`);
}

